-- Refresh verified product-learning copy from official brand sources (checked 2026-09-22).

UPDATE business_kpi.seller_task_library SET material_text = 'В текущем официальном каталоге AWARD Sterilized предназначен для взрослых стерилизованных кошек. На полке «Миски» ориентируйся на конкретные позиции, например сухой AWARD Sterilized 1,5 кг с индейкой и курицей и вариант 1,5 кг с белой рыбой. Перед рекомендацией уточни возраст, текущий рацион и предпочтения по вкусу, затем сравни конкретные упаковки. Sterilized — повседневный рацион по назначению производителя; не называй его ветеринарной диетой и не обещай лечебный эффект.' WHERE code = 'KNOW-01';

UPDATE business_kpi.seller_task_library SET material_text = 'В официальном каталоге AWARD есть Monoprotein для взрослых кошек, в том числе сухой корм 1,5 кг из индейки с яблоком и артишоком, а также отдельные Monoprotein-позиции для стерилизованных кошек. Монопротеиновую линейку объясняй по конкретной карточке и упаковке, а не как универсальное «лечение аллергии». Если покупатель говорит об аллергии, непереносимости или симптомах, не ставь диагноз и предложи согласовать рацион с ветеринарным врачом.' WHERE code = 'KNOW-02';

UPDATE business_kpi.seller_task_library SET material_text = 'AWARD Veterinary Diet — отдельная линейка ветеринарных диет. В актуальном официальном разделе есть Gastrointestinal, Hypoallergenic, Renal, Urinary для кошек, а также Diabetic/Obesity и Hepatic для собак. Производитель настоятельно рекомендует консультацию ветеринарного врача перед применением и относит продолжительность курса/смену диеты к решению специалиста. Продавец находит нужную назначенную позицию, сверяет вид животного и объясняет данные упаковки, но не назначает диету самостоятельно.' WHERE code = 'KNOW-03';

UPDATE business_kpi.seller_task_library SET material_text = 'У «Мнямс» есть корма и лакомства для кошек и собак с разными назначениями и форматами. В актуальном каталоге для кошек есть, например, паучи 85 г «На каждый день»: с кроликом для стерилизованных кошек, с лососем для стерилизованных кошек, с уткой для домашних кошек; отдельно есть лакомства и функциональные линии, включая Dental. Сначала уточни, нужен полнорационный корм или лакомство, вид/возраст питомца и задачу. Норму, ограничения и полнорационность проверяй на конкретной упаковке.' WHERE code = 'KNOW-06';

UPDATE business_kpi.seller_task_library SET material_text = 'Cat’s Choice тофу 6 л / 2,5 кг в официальном каталоге обозначен как растительный комкующийся наполнитель; древесный Cat’s Choice — впитывающий. При переходе с древесного на тофу не говори просто «этот лучше»: уточни тип лотка, чем пользовались раньше, отношение к ароматам и удобный способ уборки. Затем сравни конкретные упаковки и инструкцию.' WHERE code = 'KNOW-07';

UPDATE business_kpi.seller_task_library SET material_text = 'В текущем официальном каталоге Cat’s Choice есть растительный комкующийся тофу 6 л / 2,5 кг, силикагелевый впитывающий 5 л / 2 кг, древесный впитывающий и другие варианты. Подбор начинай не с бренда, а с вопросов: какой наполнитель сейчас, какой лоток, что не устраивает, важен ли аромат, как часто убирают и какой объём нужен. Использование и утилизацию объясняй только по конкретной упаковке.' WHERE code = 'KNOW-08';

UPDATE business_kpi.seller_task_library SET material_text = 'В ассортименте «Миски» по противопаразитарной категории ориентируйся на конкретные препараты, например Inspector для кошек/собак и маленьких питомцев, а также спреи БАРС для кошек и собак. Перед продажей обязательно уточни вид животного, точный вес/возраст, если этого требует инструкция, и нужную задачу. Не переноси дозировку и ограничения между кошачьими и собачьими формами, не угадывай интервал обработки и совместимость нескольких препаратов. Покажи официальную инструкцию; при симптомах, осложнениях или запросе на лечение направь к ветеринарному врачу.' WHERE code = 'KNOW-09';

UPDATE business_kpi.seller_task_library SET material_text = 'В ассортименте Japan Premium Pet / Premium Pet есть средства повседневного ухода за кожей и шерстью, глазами, ушами и пастью. Например, официально представлены влажные салфетки для базового ухода за пастью, ушами и глазами собак и кошек. Подбирай средство по виду животного, зоне применения и способу использования из официальной карточки. Если покупатель описывает боль, воспаление, выделения, раны или другой симптом, не превращай гигиенический товар в лечение — направь к ветеринарному врачу.' WHERE code = 'KNOW-10';

UPDATE business_kpi.seller_task_library SET material_text = 'Официальный сайт Craftia относит бренд к ультрапремиальным кормам для собак и кошек на основе свежеприготовленного мяса и заявляет отсутствие эмульгаторов, ароматизаторов, красителей и консервантов, а также технологию Nutribiome. У бренда есть разные рецепты, поэтому сначала уточни вид и возраст питомца, затем сверяй конкретную упаковку, назначение, рецепт, норму кормления и актуальную энергетическую ценность. Не переноси свойства одного рецепта Craftia на всю линейку.' WHERE code = 'KNOW-22';

UPDATE business_kpi.seller_task_library SET material_text = 'Bambini Pets — российский бренд товаров для грызунов, кроликов и птиц. Официальный сайт показывает корма, лакомства, наполнители, домики и гамаки, минеральные камни и сепию, игрушки для грызунов/кроликов и птиц. Для игрушек, включая позиции из люфы, сначала уточни вид питомца, затем проверь размер, материал, назначение и ограничения конкретного артикула на упаковке.' WHERE code = 'KNOW-23';

UPDATE business_kpi.seller_task_library SET material_text = '«Ферма кота Фёдора» выпускает сухие и влажные корма и лакомства для кошек и котят. В официальном каталоге есть отдельные влажные позиции для котят и для взрослых кошек; в лакомствах есть крем-лакомства, палочки и хрустящие подушечки. При консультации сначала проверь возрастную/физиологическую группу конкретного товара, полнорационность и норму кормления, а не делай выводы только по бренду.' WHERE code = 'KNOW-24';

UPDATE business_kpi.seller_task_library SET material_text = 'Официальный Premium Pet представляет японские товары Japan Premium Pet и другие японские зоотовары: уход за кожей/шерстью, глазами и ушами, груминг, наполнители, игрушки, амуницию и другие категории. Для конкретного средства сверяй вид животного, зону применения, формат и инструкцию. Например, есть влажные салфетки для базового ухода за пастью, ушами и глазами собак и кошек. Если есть симптом или запрос на лечение, продавец не ставит диагноз и не обещает медицинский результат.' WHERE code = 'KNOW-25';
